package thaumcraft.verification;

import com.google.gson.*;
import com.mojang.blaze3d.vertex.*;
import java.nio.file.*;
import java.util.*;
import net.minecraft.client.model.geom.ModelPart;
import net.minecraft.client.renderer.*;
import net.minecraft.client.renderer.texture.OverlayTexture;
import net.minecraft.resources.ResourceLocation;
import net.neoforged.api.distmarker.Dist;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import net.neoforged.neoforge.client.event.ClientTickEvent;
import org.joml.Matrix4f;
import org.joml.Vector3f;
import org.joml.Quaternionf;

/** Native mesh against unchanged owned TC4 animation and MC1.7.10 cube bytecode, plus GPU draws. */
@EventBusSubscriber(modid="thaumcraft_r3_test",value=Dist.CLIENT)
public final class ClientGolemVerification {
    private static boolean done;
    @SubscribeEvent public static void tick(ClientTickEvent.Post event)throws Exception{
        if(done||!"golem-client".equals(System.getProperty("thaumcraft.r3.phase")))return;
        var mc=net.minecraft.client.Minecraft.getInstance();if(!(mc.screen instanceof net.minecraft.client.gui.screens.TitleScreen)||mc.getOverlay()!=null)return;done=true;
        var path=Path.of(System.getProperty("thaumcraft.r3.root"));var result=new JsonObject();var checks=new ArrayList<String>();
        try{
            var reference=JsonParser.parseString(Files.readString(path.resolve("analysis/full_port/original-golem-model.json"))).getAsJsonObject();var originals=reference.getAsJsonObject("parts");
            Class<?> modelClass=Class.forName("thaumcraft.client.EldritchGolemModel");var ctor=modelClass.getDeclaredConstructor();ctor.setAccessible(true);var field=modelClass.getDeclaredField("parts");field.setAccessible(true);var render=modelClass.getDeclaredMethod("renderToBuffer",PoseStack.class,VertexConsumer.class,int.class,int.class,int.class);render.setAccessible(true);
            var arm=modelClass.getDeclaredMethod("animateArms",int.class,float.class,float.class,float.class);arm.setAccessible(true);var animate=modelClass.getDeclaredMethod("animate",int.class,boolean.class,float.class,float.class,float.class,float.class);animate.setAccessible(true);
            Object model=ctor.newInstance();@SuppressWarnings("unchecked")var parts=(Map<String,ModelPart>)field.get(model);require(parts.size()==36,"all36 original construct parts baked",checks);
            for(var entry:originals.entrySet()){
                var expected=entry.getValue().getAsJsonObject();var part=parts.get(entry.getKey());var pivot=expected.getAsJsonArray("pivot");var rotation=expected.getAsJsonArray("rotation");for(int i=0;i<3;i++){near(new float[]{part.x,part.y,part.z}[i],pivot.get(i).getAsFloat(),"original pivot "+entry.getKey());near(new float[]{part.xRot,part.yRot,part.zRot}[i],rotation.get(i).getAsFloat(),"original initial rotation "+entry.getKey());}
                require(true,"original pivot/initial angle "+entry.getKey(),checks);
                parts.values().forEach(p->p.visible=false);part.visible=true;part.x=part.y=part.z=part.xRot=part.yRot=part.zRot=0;var capture=new Capture();part.render(new PoseStack(),capture,0xf000f0,OverlayTexture.NO_OVERLAY);compare(capture.vertices,expected.getAsJsonArray("boxes").get(0).getAsJsonObject().getAsJsonArray("vertices"),new Matrix4f());require(true,"all24 original MC cube positions and UVs "+entry.getKey(),checks);
                part.resetPose();parts.values().forEach(p->p.visible=true);
            }
            for(var entry:reference.getAsJsonArray("cases")){
                var row=entry.getAsJsonObject();model=ctor.newInstance();@SuppressWarnings("unchecked")var animated=(Map<String,ModelPart>)field.get(model);int spawn=row.get("spawn").getAsInt(),attack=row.get("attack").getAsInt();boolean headless=row.get("headless").getAsBoolean();float walk=row.get("walk").getAsFloat(),amount=row.get("amount").getAsFloat();arm.invoke(model,attack,walk,amount,row.get("partial").getAsFloat());animate.invoke(model,spawn,headless,walk,amount,row.get("yaw").getAsFloat(),row.get("pitch").getAsFloat());var angles=row.getAsJsonObject("rotation");for(var bone:animated.entrySet()){var expected=angles.getAsJsonArray(bone.getKey());near(bone.getValue().xRot,expected.get(0).getAsFloat(),"animated x "+bone.getKey());near(bone.getValue().yRot,expected.get(1).getAsFloat(),"animated y "+bone.getKey());near(bone.getValue().zRot,expected.get(2).getAsFloat(),"animated z "+bone.getKey());}require(true,"original animation spawn="+spawn+" attack="+attack+" headless="+headless+" walk="+walk,checks);
                var capture=new Capture();render.invoke(model,new PoseStack(),capture,0xf000f0,OverlayTexture.NO_OVERLAY,-1);var draws=row.getAsJsonArray("draws");require(capture.vertices.size()==draws.size()*24,"original render count including repeated cloth and child joints",checks);int offset=0;for(var name:draws){String bone=name.getAsString();var expected=originals.getAsJsonObject(bone);var matrix=transform(bone,originals,angles);compare(capture.vertices.subList(offset,offset+24),expected.getAsJsonArray("boxes").get(0).getAsJsonObject().getAsJsonArray("vertices"),matrix);offset+=24;}require(true,"complete original ordered geometry and UVs for animation case",checks);
                var pose=new PoseStack();pose.translate(0,0,-100);render.invoke(model,pose,mc.renderBuffers().bufferSource().getBuffer(RenderType.entityTranslucent(ResourceLocation.parse("thaumcraft:textures/models/eldritch_golem.png"))),0xf000f0,OverlayTexture.NO_OVERLAY,-1);mc.renderBuffers().bufferSource().endBatch();require(org.lwjgl.opengl.GL11.glGetError()==0,"native construct GPU draw without GL error",checks);
            }
            var dispatcherField=net.minecraft.client.renderer.entity.EntityRenderDispatcher.class.getDeclaredField("renderers");dispatcherField.setAccessible(true);var registered=(Map<?,?>)dispatcherField.get(mc.getEntityRenderDispatcher());
            require(registered.get(thaumcraft.entities.R5Entities.ELDRITCH_GOLEM.get()).getClass().getName().endsWith("EldritchGolemRenderer"),"construct renderer registered with actual entity dispatcher",checks);require(registered.get(thaumcraft.entities.R5Entities.SPECIAL_ITEM.get()) instanceof net.minecraft.client.renderer.entity.ItemEntityRenderer,"special loot uses actual registered item renderer",checks);
            Object orb=registered.get(thaumcraft.entities.R5Entities.GOLEM_ORB.get());require(orb!=null&&orb.getClass().getName().endsWith("GolemOrbRenderer"),"distinct electric orb renderer registered",checks);var draw=orb.getClass().getDeclaredMethod("draw",int.class,boolean.class,float.class,float.class,PoseStack.class,MultiBufferSource.class);draw.setAccessible(true);mc.getEntityRenderDispatcher().overrideCameraOrientation(new Quaternionf());
            for(int ticks=0;ticks<30;ticks++)for(boolean red:new boolean[]{false,true}){var capture=new Capture();draw.invoke(orb,ticks,red,0f,0f,new PoseStack(),(MultiBufferSource)type->capture);require(capture.vertices.size()==4,"orb native quad",checks);float u=(1+ticks%6)/8f,v=red?.75f:.875f;float[][] uv={{u,v+.125f},{u+.125f,v+.125f},{u+.125f,v},{u,v}};for(int i=0;i<4;i++){near(capture.vertices.get(i)[3],uv[i][0],"original electric orb U");near(capture.vertices.get(i)[4],uv[i][1],"original electric orb V");require(capture.vertices.get(i)[8]==204,"original electric orb alpha.8",checks);}float size=1+(net.minecraft.util.Mth.sin(ticks/5f)*.2f+.2f);for(var vertex:capture.vertices)near((float)Math.sqrt(vertex[0]*vertex[0]+vertex[1]*vertex[1]+vertex[2]*vertex[2]),size/(float)Math.sqrt(2),"original pulsing electric orb extent");require(true,"original orb6-frame"+(red?"red":"blue")+" UV, pulse and colour tick="+ticks,checks);var pose=new PoseStack();pose.translate(0,0,-100);draw.invoke(orb,ticks,red,0f,0f,pose,mc.renderBuffers().bufferSource());mc.renderBuffers().bufferSource().endBatch();require(org.lwjgl.opengl.GL11.glGetError()==0,"electric orb GPU draw without GL error",checks);}
            var orbControls=JsonParser.parseString(Files.readString(path.resolve("analysis/full_port/original-golem-orb.json"))).getAsJsonArray();require(orbControls.size()==400,"400 unchanged original electric orb renderer controls",checks);
            for(var entry:orbControls){var row=entry.getAsJsonObject();var capture=new Capture();draw.invoke(orb,row.get("ticks").getAsInt(),row.get("red").getAsBoolean(),row.get("yaw").getAsFloat(),row.get("pitch").getAsFloat(),new PoseStack(),(MultiBufferSource)type->capture);var original=row.getAsJsonArray("vertices");require(capture.vertices.size()==original.size(),"original orb vertex count",checks);for(int i=0;i<4;i++){var expected=original.get(i).getAsJsonArray();var actual=capture.vertices.get(i);for(int c=0;c<5;c++)near(actual[c],expected.get(c).getAsFloat(),"unchanged original electric orb position/UV");near(actual[8]/255f,row.get("alpha").getAsFloat(),"unchanged original electric orb opacity");}require(capture.light==row.get("light").getAsInt(),"original electric orb light220",checks);require(true,"unchanged original electric orb camera/pulse/UV tick="+row.get("ticks")+" yaw="+row.get("yaw")+" pitch="+row.get("pitch")+" red="+row.get("red"),checks);}
            for(String texture:List.of("models/eldritch_golem","misc/particles","misc/nodes","misc/beamh")){var id=ResourceLocation.parse("thaumcraft:textures/"+texture+".png");mc.getTextureManager().bindForSetup(id);require(mc.getTextureManager().getTexture(id).getId()>0,"original construct/orb/effect texture uploaded "+texture,checks);}
            result.addProperty("passed",true);result.addProperty("driver",org.lwjgl.opengl.GL11.glGetString(org.lwjgl.opengl.GL11.GL_RENDERER));
        }catch(Throwable failure){result.addProperty("passed",false);result.addProperty("error",failure.toString());failure.printStackTrace();}
        var hashes=new JsonObject();for(String resource:List.of("thaumcraft/client/EldritchGolemModel.class","thaumcraft/client/EldritchGolemRenderer.class","thaumcraft/client/GolemOrbRenderer.class","thaumcraft/client/GolemClientEffects.class","thaumcraft/client/GolemClientEffects$Sprite.class","thaumcraft/client/GolemClientEffects$Arc.class","thaumcraft/client/OuterRoomRenderers.class","assets/thaumcraft/entity_models/eldritch_golem.json","assets/thaumcraft/textures/models/eldritch_golem.png","assets/thaumcraft/textures/misc/particles.png","assets/thaumcraft/textures/misc/nodes.png","assets/thaumcraft/textures/misc/beamh.png")){try(var stream=ClientGolemVerification.class.getClassLoader().getResourceAsStream(resource)){if(stream==null)throw new AssertionError("Missing runtime construct resource "+resource);hashes.addProperty(resource,HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(stream.readAllBytes())));}}
        result.add("payload_sha256",hashes);result.add("checks",new Gson().toJsonTree(checks));result.addProperty("count",checks.size());result.addProperty("time",java.time.Instant.now().toString());result.addProperty("manual_acceptance","pending");result.addProperty("live_particle_motion","pending world fixture");Files.writeString(path.resolve("analysis/full_port/golem-client.json"),new GsonBuilder().setPrettyPrinting().create().toJson(result)+"\n");mc.stop();
    }
    private static Matrix4f transform(String name,JsonObject parts,JsonObject angles){var part=parts.getAsJsonObject(name);var parent=part.get("parent");var matrix=parent.isJsonNull()?new Matrix4f():transform(parent.getAsString(),parts,angles);var p=part.getAsJsonArray("pivot");var r=angles.getAsJsonArray(name);return matrix.translate(p.get(0).getAsFloat()/16,p.get(1).getAsFloat()/16,p.get(2).getAsFloat()/16).rotateZYX(r.get(2).getAsFloat(),r.get(1).getAsFloat(),r.get(0).getAsFloat());}
    private static void compare(List<float[]> actual,JsonArray original,Matrix4f matrix){if(actual.size()!=24)throw new AssertionError("Model cube must contain24 vertices");var remaining=new ArrayList<>(actual);for(var entry:original){var row=entry.getAsJsonArray();var position=new Vector3f(row.get(0).getAsFloat(),row.get(1).getAsFloat(),row.get(2).getAsFloat());matrix.transformPosition(position);float[] expected={position.x,position.y,position.z,row.get(3).getAsFloat(),row.get(4).getAsFloat()};boolean found=false;for(var it=remaining.iterator();it.hasNext();){var vertex=it.next();boolean same=true;for(int i=0;i<5;i++)same&=Math.abs(vertex[i]-expected[i])<2e-6;if(same){it.remove();found=true;break;}}if(!found)throw new AssertionError("Original construct position/UV missing: "+Arrays.toString(expected));}}
    private static void near(float actual,float expected,String message){if(!Float.isFinite(actual)||!Float.isFinite(expected)||Math.abs(actual-expected)>2e-6)throw new AssertionError(message+": "+actual+" / "+expected);}
    private static void require(boolean pass,String message,List<String> checks){if(!pass)throw new AssertionError(message);checks.add(message);}
    private static final class Capture implements VertexConsumer{final List<float[]> vertices=new ArrayList<>();int light;public VertexConsumer addVertex(float x,float y,float z){vertices.add(new float[]{x,y,z,0,0,0,0,0,0});return this;}public VertexConsumer setUv(float u,float v){var p=vertices.getLast();p[3]=u;p[4]=v;return this;}public VertexConsumer setColor(int r,int g,int b,int a){var p=vertices.getLast();p[5]=r;p[6]=g;p[7]=b;p[8]=a;return this;}public VertexConsumer setUv1(int u,int v){return this;}public VertexConsumer setUv2(int u,int v){light=u|(v<<16);return this;}public VertexConsumer setNormal(float x,float y,float z){return this;}}
    private ClientGolemVerification(){}
}
